5	pub(crate) struct FormatHtmlClosingElement {
6	    /// Whether or not the `</tag` part is borrowed by the children of the element (aka [`HtmlElementList`][HtmlElementList]). See also: [`FormatHtmlElementList`][FormatHtmlElementList]
7	    ///
8	    /// In this context "borrowed" tokens refers to tokens that would normally be formatted by this formatter, but are instead formatted by the sibling `HtmlElementList`.
9	    /// This is necessary to get the correct tokens in the right groups so that we don't accidentally add whitespace inside elements when we shouldn't. See also: [`crate::context::WhitespaceSensitivity]
10	    ///
11	    /// [FormatHtmlElementList]: crate::html::lists::element_list::FormatHtmlElementList
12	    /// [HtmlElementList]: biome_html_syntax::HtmlElementList
13	    tag_borrowed: bool,
14	    /// Whether or not the closing `>` is borrowed by an adjacent sibling element.
15	    /// When true, the `>` will be printed by the next sibling element instead of this closing tag.
16	    r_angle_borrowed: bool,
17	}
18	pub(crate) struct FormatHtmlClosingElementOptions {
19	    /// Whether or not the `</tag` part of this tag is borrowed, and therefore managed by a different formatter.
20	    pub tag_borrowed: bool,
21	    /// Whether or not the closing `>` is borrowed by an adjacent sibling element.
22	    pub r_angle_borrowed: bool,
23	}
