93	        // If there is leading whitespace before a leading comment, we need to preserve it because it's probably indentation.
94	        // See prettier test case: crates/biome_html_formatter/tests/specs/prettier/html/comments/hidden.html
95	        // The current implementation for `biome_formatter::FormatTrailingComments` actually has a ton of js specific behavior that we don't want in the html formatter.
96	
97	        let comments = f.context().comments().clone();
98	        let trailing_comments = comments.trailing_comments(node.syntax());
99	        for comment in trailing_comments {
