101	                comment,
102	                <HtmlFormatContext as CstFormatContext>::CommentRule::default(),
103	            );
104	            match comment.lines_before() {
105	                0 => {}
106	                1 => write!(f, [hard_line_break()])?,
107	                _ => write!(f, [empty_line()])?,
108	            }
109	            write!(f, [format_comment])?;
110	            comment.mark_formatted();
111	        }
112	
113	        Ok(())
114	    }
